                        const cells = [...r.children].filter((c) => !c.classList.contains("nl2-reroi-c"));
                        const num = (c) => { const v = parseFloat(String(c ? c.textContent : "").replace(/[^0-9.\-]/g, "")); return isFinite(v) ? v : 0; };
