                                    return cargo;
                                const snap = d.resourceSnapshot || null, st = (snap && snap.storage) || {}, res = (snap && snap.resources) || fresh;
                                const room = Object.fromEntries(RES.map(([k]) => [k, Math.max(0, (st[k] != null ? num(st[k]) : num(fresh.basicStorage)) - num(res[k]))]));
